// SPDX-License-Identifier: MIT
//! vectors -- external, byte-exact test vectors mechanically extracted from
//! the W3C Web Authentication (WebAuthn) Level 3 specification, section 16
//! "Test Vectors" (https://www.w3.org/TR/webauthn-3/#sctn-test-vectors,
//! non-normative but the spec's own official conformance vectors).
//!
//! Provenance: fetched from https://www.w3.org/TR/webauthn-3/ on 2026-07-21
//! and extracted with a small offline Python script (HTML tag-strip + regex
//! on the `name = h'...'` CDDL literals the spec uses, plus a byte-level scan
//! to pull the `credentialPublicKey` out of each registration vector's own
//! `authData` -- the spec's prose does not give that value as a separate
//! named literal, only embedded inside `attestationObject`). This mechanical
//! extraction -- rather than hand-transcription -- is deliberate: an early
//! hand-copy of these vectors had a transcription slip (one signature
//! substring pasted into the wrong test case); this file is regenerated
//! straight from the spec text to make that class of error impossible.
//! Cross-checked: every case's `credential_id` recomputed here from
//! `attestationObject.authData` matches the value the spec states
//! separately (`credential_id = h'...'`) byte-for-byte.
//!
//! Per §16's preamble: "All examples use the RP ID example.org, the origin
//! https://example.org [...]. All random values are deterministically
//! generated using HKDF-SHA-256 [...]. ECDSA signatures use a deterministic
//! nonce [RFC6979]." -- i.e. these are not this project's own generated
//! fixtures; they are the spec authors' own reproducible-by-construction
//! conformance vectors, independent of this module's implementation --
//! exactly the anti-self-consistency anchor a security-critical verifier
//! needs (a self-consistent-but-wrong ES256/EdDSA/RS256 or CBOR/COSE
//! implementation would fail these, since the bytes were produced by the
//! spec's own reference implementation, not this module's encoder).

const std = @import("std");

fn hexLit(comptime hex: []const u8) [hex.len / 2]u8 {
    comptime {
        @setEvalBranchQuota(200_000);
        var out: [hex.len / 2]u8 = undefined;
        _ = std.fmt.hexToBytes(&out, hex) catch unreachable;
        return out;
    }
}

pub const rp_id = "example.org";
pub const origin = "https://example.org";

